EXPLAIN ANALYZE SELECT t.id,t.user_id,t.category_id,t.group_id,t.assignee_id,t.title,t.description,t.priority,t.status,t.version,t.sla_policy_id,t.response_minutes,t.resolve_minutes,t.auto_escalate,t.response_deadline,t.resolve_deadline,t.first_response_at,t.resolved_at,t.closed_at,t.cancelled_at,t.created_at,t.updated_at,t.sla_cycle,t.cycle_started_at,t.response_breached,t.resolve_breached,t.escalation_level FROM ticket t JOIN support_group g ON g.id=t.group_id WHERE t.user_id=2 ORDER BY t.created_at DESC,t.id DESC LIMIT 20 OFFSET 0;
EXPLAIN ANALYZE SELECT t.id,t.response_deadline AS deadline FROM ticket t WHERE t.status IN ('CREATED','ASSIGNED','PROCESSING','PENDING') AND t.first_response_at IS NULL AND t.response_deadline<=UTC_TIMESTAMP(6)+INTERVAL 300 SECOND AND (t.response_deadline>'1970-01-01' OR (t.response_deadline='1970-01-01' AND t.id>0)) AND NOT EXISTS(SELECT 1 FROM sla_event e WHERE e.ticket_id=t.id AND e.sla_cycle=1 AND e.type=CASE WHEN t.response_deadline<UTC_TIMESTAMP(6) THEN 'RESPONSE_BREACHED' ELSE 'RESPONSE_WARNING' END) ORDER BY t.response_deadline,t.id LIMIT 100;
EXPLAIN ANALYZE SELECT event_id,aggregate_id,payload,attempts FROM outbox_event WHERE (status='PENDING' AND available_at<=UTC_TIMESTAMP(6)) OR (status='PROCESSING' AND lease_until<=UTC_TIMESTAMP(6)) ORDER BY available_at,event_id LIMIT 1 FOR UPDATE SKIP LOCKED;
